package cz.mh.rallye.rallye_backend.administration;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.boot.servlet.autoconfigure.MultipartProperties;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.util.unit.DataSize;
import tools.jackson.databind.json.JsonMapper;
import cz.mh.rallye.rallye_backend.administration.application.AboutConfiguration;
import cz.mh.rallye.rallye_backend.audit.application.AuditRetentionService;
import cz.mh.rallye.rallye_backend.identity.application.*;
import cz.mh.rallye.rallye_backend.templates.application.TemplateFileContent;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class AboutConfigurationTest {
 @Test void allowlistUsesEffectiveValuesWithoutSerializingSecrets(){var env=new MockEnvironment().withProperty("rallye.auth.secure-cookies","false").withProperty("rallye.simulation.cleanup-delay-ms","1250").withProperty("spring.datasource.password","DO_NOT_LEAK_PASSWORD").withProperty("spring.datasource.url","jdbc:postgresql://private-host/db").withProperty("user.home","/private/path").withProperty("rallye.audit.cleanup-enabled","false");env.setActiveProfiles("local");var audit=mock(AuditRetentionService.class);when(audit.retentionDays()).thenReturn(400L);var files=new TemplateFileContent(204800,20971520);var multipart=new MultipartProperties();multipart.setMaxFileSize(DataSize.ofMegabytes(50));multipart.setMaxRequestSize(DataSize.ofMegabytes(51));var external=new ExternalProviders.Settings(Map.of(ExternalProviders.Provider.GOOGLE,new ExternalProviders.Client(true,"DO_NOT_LEAK_CLIENT","DO_NOT_LEAK_TOKEN","https://private-host/callback")),Map.of("web","https://private-host/return"));var apple=new AppleClientSecrets.Settings(false,"DO_NOT_LEAK_TEAM","DO_NOT_LEAK_KEY","/private/key",Set.of("DO_NOT_LEAK_CLIENT"));var config=new AboutConfiguration(env,audit,files,multipart,external,apple);var v=config.read();assertEquals(400,v.auditRetentionDays());assertEquals(24,v.idempotencyHours());assertEquals(2000,v.limits().registrationMembersTextCodePoints());assertEquals(100,v.limits().registrationMaxPageSize());assertEquals(204800,v.limits().files().markdownMaxBytes());assertEquals(20971520,v.limits().files().pdfMaxBytes());assertEquals(1250L,v.schedulers().simulationFileCleanup().intervalMilliseconds());assertEquals(30000L,v.schedulers().lifecycle().intervalMilliseconds());assertFalse(v.schedulers().auditCleanup().enabled());assertEquals("0 15 3 * * *",v.schedulers().auditCleanup().cron());assertEquals("Europe/Prague",v.schedulers().auditCleanup().timezone());assertTrue(v.security().googleProviderEnabled());assertFalse(v.security().secureCookies());assertEquals(24,v.security().sessionIdleHours());assertEquals(30,v.security().rememberedSessionIdleDays());String json=JsonMapper.builder().build().writeValueAsString(v);for(String forbidden:List.of("DO_NOT_LEAK","private-host","/private/","jdbc:","clientSecret","password"))assertFalse(json.contains(forbidden));env.setActiveProfiles("it");assertFalse(config.read().schedulers().lifecycle().enabled());assertFalse(config.read().schedulers().simulationFileCleanup().enabled());}
 @Test void scheduledDurationUsesSameUnitsAndDefaultAsRuntime(){var env=new MockEnvironment();var a=mock(AuditRetentionService.class);var c=new AboutConfiguration(env,a,new TemplateFileContent(102400,10485760),new MultipartProperties(),new ExternalProviders.Settings(null,null),new AppleClientSecrets.Settings(false,null,null,null,null));assertEquals(600000L,c.read().schedulers().simulationFileCleanup().intervalMilliseconds());env.setProperty("rallye.simulation.cleanup-delay-ms","PT2S");assertEquals(2000L,c.read().schedulers().simulationFileCleanup().intervalMilliseconds());}
}
